// =========================================================================
// NẠP ĐẦU VÀO: BẠN CÓ THỂ ĐIỀN CHỦ ĐỀ TÙY Ý HOẶC ĐỂ TỰ ĐỘNG CHỌN
// =========================================================================

const sampleTopics = [
  {
    brand_or_product: "Mỹ Nghệ Đông Phong",
    topic: "Vòng tay gỗ Tử Đàn Tiểu Diệp Ấn Độ phôi già chìm nước",
    core_benefit: "Mùi thơm tự nhiên giúp tĩnh tâm, xua tan áp lực thương trường, tôm gỗ mịn lên nước bóng ngọc cổ kính",
    target_audience: "Doanh nhân, người làm kinh doanh thích thú chơi mộc sâu sắc, sợ mua phải gỗ non nhuộm màu"
  },
  {
    brand_or_product: "Mỹ Nghệ Đông Phong",
    topic: "Bút ký phong thủy gỗ Hoàng Đàn Tuyết Lạng Sơn",
    core_benefit: "Chất gỗ tự lên lớp tuyết óng ánh như ngọc, làm quà biếu đối tác thể hiện vị thế tinh tế mà không phô trương",
    target_audience: "Người tìm quà tặng sang trọng, ý nghĩa phong thủy cho sếp hoặc đối tác lớn"
  },
  {
    brand_or_product: "Mỹ Nghệ Đông Phong",
    topic: "Vòng Nu Bách Xanh Mộc Châu chớp vân biến ảo",
    core_benefit: "Mùi thơm ngọt sắc kéo dài hàng chục năm, thớ nu biến hóa độc nhất vô nhị",
    target_audience: "Người sành gỗ thích sưu tầm vân nu độc bản, tìm kiếm sự an yên và vượng khí"
  }
];

// Chọn 1 chủ đề ngẫu nhiên hoặc lấy từ Webhook/Trigger
const chosen = sampleTopics[Math.floor(Math.random() * sampleTopics.length)];

return {
  brand_or_product: chosen.brand_or_product,
  topic: chosen.topic,
  core_benefit: chosen.core_benefit,
  target_audience: chosen.target_audience,
  timestamp: new Date().toISOString()
};

